begin;
with j as (select * from jsonb_to_recordset($law7d0022$[{"code_id":"GK_RF","article_number":"218","version_date":"1994-11-30","article_text":"1. Право собственности на новую вещь, изготовленную или созданную лицом для себя с соблюдением закона и иных правовых актов, приобретается этим лицом.\n\nПраво собственности на плоды, продукцию, доходы, полученные в результате использования имущества, приобретается по основаниям, предусмотренным статьей 136 настоящего Кодекса.\n\n2. Право собственности на имущество, которое имеет собственника, может быть приобретено другим лицом на основании договора купли-продажи, мены, дарения или иной сделки об отчуждении этого имущества.\n\nВ случае смерти гражданина право собственности на принадлежавшее ему имущество переходит по наследству к другим лицам в соответствии с завещанием или законом.\n\nВ случае реорганизации юридического лица право собственности на принадлежавшее ему имущество переходит к юридическим лицам - правопреемникам реорганизованного юридического лица.\n\n3. В случаях и в порядке, предусмотренных настоящим Кодексом, лицо может приобрести право собственности на имущество, не имеющее собственника, на имущество, собственник которого неизвестен, либо на имущество, от которого собственник отказался или на которое он утратил право собственности по иным основаниям, предусмотренным законом.\n\n4. Член жилищного, жилищно-строительного, дачного, гаражного или иного потребительского кооператива, другие лица, имеющие право на паенакопления, полностью внесшие свой паевой взнос за квартиру, дачу, гараж, иное помещение, предоставленное этим лицам кооперативом, приобретают право собственности на указанное имущество.","article_title":"Статья 218. Основания приобретения права собственности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f491c174ffc81db266e49e2329200a0a266b55732784c88a690f162ea441f1cb"},{"code_id":"GK_RF","article_number":"219","version_date":"1994-11-30","article_text":"Право собственности на здания, сооружения и другое вновь создаваемое недвижимое имущество, подлежащее государственной регистрации, возникает с момента такой регистрации.","article_title":"Статья 219. Возникновение права собственности на вновь создаваемое недвижимое имущество","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"20416658158856cb439dd0bbfd8fbd75373767f6f7bb65d81e6fa5d3ddb8b18e"},{"code_id":"GK_RF","article_number":"22","version_date":"1994-11-30","article_text":"1. Никто не может быть ограничен в правоспособности и дееспособности иначе, как в случаях и в порядке, установленных законом.\n\n2. Несоблюдение установленных законом условий и порядка ограничения дееспособности граждан или их права заниматься предпринимательской либо иной деятельностью влечет недействительность акта государственного или иного органа, устанавливающего соответствующее ограничение.\n\n3. Полный или частичный отказ гражданина от правоспособности или дееспособности и другие сделки, направленные на ограничение правоспособности или дееспособности, ничтожны, за исключением случаев, когда такие сделки допускаются законом.","article_title":"Статья 22. Недопустимость лишения и ограничения правоспособности и дееспособности гражданина","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1242579557626b387d738ed1b5dfe5f83c12d11d4c020bfc8911813c5996cf7b"},{"code_id":"GK_RF","article_number":"220","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено договором, право собственности на новую движимую вещь, изготовленную лицом путем переработки не принадлежащих ему материалов, приобретается собственником материалов.\n\nОднако если стоимость переработки существенно превышает стоимость материалов, право собственности на новую вещь приобретает лицо, которое, действуя добросовестно, осуществило переработку для себя.\n\n2. Если иное не предусмотрено договором, собственник материалов, приобретший право собственности на изготовленную из них вещь, обязан возместить стоимость переработки осуществившему ее лицу, а в случае приобретения права собственности на новую вещь этим лицом последнее обязано возместить собственнику материалов их стоимость.\n\n3. Собственник материалов, утративший их в результате недобросовестных действий лица, осуществившего переработку, вправе требовать передачи новой вещи в его собственность и возмещения причиненных ему убытков.","article_title":"Статья 220. Переработка","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"da98c1c1919f47a7e7b6569ba372f6a1700cca77135d19b4bbaa4fe60fd9b6a9"},{"code_id":"GK_RF","article_number":"221","version_date":"1994-11-30","article_text":"В случаях, когда в соответствии с законом, общим разрешением, данным собственником, или в соответствии с местным обычаем на определенной территории допускается сбор ягод, добыча (вылов) рыбы и других водных биологических ресурсов, сбор или добыча других общедоступных вещей и животных, право собственности на соответствующие вещи приобретает лицо, осуществившее их сбор или добычу. (В редакции федеральных законов от 03.06.2006 № 73-ФЗ; от 04.12.2006 № 201-ФЗ; от 06.12.2007 № 333-ФЗ)","article_title":"Статья 221. Обращение в собственность общедоступных для сбора вещей","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8d56e105976c27a63d6ffbb76135b14b8a66c69ec4bcf86ed317eea8b68f1777"},{"code_id":"GK_RF","article_number":"222","version_date":"1994-11-30","article_text":"1. Самовольной постройкой является здание, сооружение или другое строение, возведенные или созданные на земельном участке, не предоставленном в установленном порядке, или на земельном участке, разрешенное использование которого не допускает строительства на нем данного объекта, либо возведенные или созданные без получения на это необходимых в силу закона согласований, разрешений или с нарушением градостроительных и строительных норм и правил, если разрешенное использование земельного участка, требование о получении соответствующих согласований, разрешений и (или) указанные градостроительные и строительные нормы и правила установлены на дату начала возведения или создания самовольной постройки и являются действующими на дату выявления самовольной постройки.\n\nНе является самовольной постройкой здание, сооружение или другое строение, возведенные или созданные с нарушением установленных в соответствии с законом ограничений использования земельного участка, если собственник данного объекта не знал и не мог знать о действии указанных ограничений в отношении принадлежащего ему земельного участка.\n\n(Пункт в редакции Федерального закона от 03.08.2018 № 339-ФЗ)\n\n2. Лицо, осуществившее самовольную постройку, не приобретает на нее право собственности. Оно не вправе распоряжаться постройкой - продавать, дарить, сдавать в аренду, совершать другие сделки.\n\nАбзац. (Утратил силу - Федеральный закон от 03.08.2018 № 339-ФЗ)\n\nИспользование самовольной постройки не допускается. (Дополнение абзацем - Федеральный закон от 03.08.2018 № 339-ФЗ)\n\nСамовольная постройка подлежит сносу или приведению в соответствие с параметрами, установленными правилами землепользования и застройки, документацией по планировке территории, или обязательными требованиями к параметрам постройки, предусмотренными законом (далее - установленные требования), осуществившим ее лицом либо за его счет, а при отсутствии сведений о нем лицом, в собственности, пожизненном наследуемом владении, постоянном (бессрочном) пользовании которого находится земельный участок, на котором возведена или создана самовольная постройка, или лицом, которому такой земельный участок, находящийся в государственной или муниципальной собственности, предоставлен во временное владение и пользование, либо за счет соответствующего лица, за исключением случаев, предусмотренных пунктом 3 настоящей статьи, и случаев, если снос самовольной постройки или ее приведение в соответствие с установленными требованиями осуществляется в соответствии с законом органом местного самоуправления. (Дополнение абзацем - Федеральный закон от 03.08.2018 № 339-ФЗ)\n\n3. Право собственности на самовольную постройку может быть признано судом, а в предусмотренных законом случаях в ином установленном законом порядке за лицом, в собственности, пожизненном наследуемом владении, постоянном (бессрочном) пользовании которого находится земельный участок, на котором создана постройка, при одновременном соблюдении следующих условий:\n\nесли в отношении земельного участка лицо, осуществившее постройку, имеет права, допускающие строительство на нем данного объекта;\n\nесли на день обращения в суд постройка соответствует установленным требованиям; (В редакции Федерального закона от 03.08.2018 № 339-ФЗ)\n\nесли сохранение постройки не нарушает права и охраняемые законом интересы других лиц и не создает угрозу жизни и здоровью граждан.\n\nВ этом случае лицо, за которым признано право собственности на постройку, возмещает осуществившему ее лицу расходы на постройку в размере, определенном судом.\n\n(Пункт в редакции Федерального закона от 13.07.2015 № 258-ФЗ)\n\n32. Лицо, в собственности, пожизненном наследуемом владении, постоянном (бессрочном) пользовании которого находится земельный участок, на котором возведена или создана самовольная постройка, и которое выполнило требование о приведении самовольной постройки в соответствие с установленными требованиями, приобретает право собственности на такие здание, сооружение или другое строение в соответствии с настоящим Кодексом.\n\nЛицо, во временное владение и пользование которому в целях строительства предоставлен земельный участок, который находится в государственной или муниципальной собственности и на котором возведена или создана самовольная постройка, приобретает право собственности на такие здание, сооружение или другое строение в случае выполнения им требования о приведении самовольной постройки в соответствие с установленными требованиями, если это не противоречит закону или договору.\n\nЛицо, которое приобрело право собственности на здание, сооружение или другое строение, возмещает лицу, осуществившему их строительство, расходы на постройку за вычетом расходов на приведение самовольной постройки в соответствие с установленными требованиями.\n\n(Дополнение пунктом - Федеральный закон от 03.08.2018 № 339-ФЗ)\n\n4. Органы местного самоуправления принимают в порядке, установленном законом:\n\n1) решение о сносе самовольной постройки в случае, если самовольная постройка возведена или создана на земельном участке, в отношении которого отсутствуют правоустанавливающие документы и необходимость их наличия установлена в соответствии с законодательством на дату начала строительства такого объекта, либо самовольная постройка возведена или создана на земельном участке, вид разрешенного использования которого не допускает строительства на нем такого объекта и который расположен в границах территории общего пользования;\n\n2) решение о сносе самовольной постройки или ее приведении в соответствие с установленными требованиями в случае, если самовольная постройка возведена или создана на земельном участке, вид разрешенного использования которого не допускает строительства на нем такого объекта, и данная постройка расположена в границах зоны с особыми условиями использования территории при условии, что режим указанной зоны не допускает строительства такого объекта, либо в случае, если в отношении самовольной постройки отсутствует разрешение на строительство, при условии, что границы указанной зоны, необходимость наличия этого разрешения установлены в соответствии с законодательством на дату начала строительства такого объекта.\n\nСрок для сноса самовольной постройки устанавливается с учетом характера самовольной постройки, но не может составлять менее чем три месяца и более чем двенадцать месяцев, срок для приведения самовольной постройки в соответствие с установленными требованиями устанавливается с учетом характера самовольной постройки, но не может составлять менее чем шесть месяцев и более чем три года.\n\nПредусмотренные настоящим пунктом решения не могут быть приняты органами местного самоуправления в отношении самовольных построек, возведенных или созданных на земельных участках, не находящихся в государственной или муниципальной собственности, кроме случаев, если сохранение таких построек создает угрозу жизни и здоровью граждан.\n\nОрганы местного самоуправления в любом случае не вправе принимать решение о сносе самовольной постройки либо решение о сносе самовольной постройки или ее приведении в соответствие с установленными требованиями в отношении объекта недвижимого имущества, право собственности на который зарегистрировано в Едином государствен\n\nном реестре недвижимости или признано судом в соответствии с пунктом 3 настоящей статьи либо в отношении которого ранее судом принято решение об отказе в удовлетворении исковых требований о сносе самовольной постройки, или в отношении многоквартирного дома, жилого дома или садового дома.\n\n(Дополнение пунктом - Федеральный закон от 13.07.2015 № 258-ФЗ) (В редакции Федерального закона от 03.08.2018 № 339-ФЗ)","article_title":"Статья 222. Самовольная постройка","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c0626ea68e86b6ce518f1d1864aa1172b6dfac60b37e23bea81e71d400c825f2"},{"code_id":"GK_RF","article_number":"223","version_date":"1994-11-30","article_text":"1. Право собственности у приобретателя вещи по договору возникает с момента ее передачи, если иное не предусмотрено законом или договором.\n\n2. В случаях, когда отчуждение имущества подлежит государственной регистрации, право собственности у приобретателя возникает с момента такой регистрации, если иное не установлено законом.\n\nНедвижимое имущество признается принадлежащим добросовестному приобретателю (пункт 1 статьи 302) на праве собственности с момента такой регистрации, за исключением предусмотренных статьей 302 настоящего Кодекса случаев, когда собственник вправе истребовать такое имущество от добросовестного приобретателя. (Дополнение абзацем - Федеральный закон от 30.12.2004 № 217-ФЗ)","article_title":"Статья 223. Момент возникновения права собственности у приобретателя по договору","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"52c9f0eed45d62107018c30e84e8031de0af83d472b2735f75be2717e5105269"},{"code_id":"GK_RF","article_number":"224","version_date":"1994-11-30","article_text":"1. Передачей признается вручение вещи приобретателю, а равно сдача перевозчику для отправки приобретателю или сдача в организацию связи для пересылки приобретателю вещей, отчужденных без обязательства доставки.\n\nВещь считается врученной приобретателю с момента ее фактического поступления во владение приобретателя или указанного им лица.\n\n2. Если к моменту заключения договора об отчуждении вещи она уже находится во владении приобретателя, вещь признается переданной ему с этого момента.\n\n3. К передаче вещи приравнивается передача коносамента или иного товарораспорядительного документа на нее.","article_title":"Статья 224. Передача вещи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"704fb0e779a29fe4f67f0ed955bd4940caaaf359500cb625fb18355b97b81f7b"},{"code_id":"GK_RF","article_number":"225","version_date":"1994-11-30","article_text":"Если иной срок не предусмотрен настоящей статьей, по истечении года со дня постановки бесхозяйной недвижимой вещи на учет орган, уполномоченный управлять муниципальным имуществом, может обратиться в суд с требованием о признании права муниципальной собственности на эту вещь. (В редакции  Федерального закона от 31.07.2025 № 315-ФЗ)\n\nБесхозяйная недвижимая вещь, не признанная по решению суда поступившей в муниципальную собственность, может быть вновь принята во владение, пользование и распоряжение оставившим ее собственником либо приобретена в собственность в силу приобретательной давности.\n\nЕсли иной срок не предусмотрен настоящей статьей, по истечении года со дня постановки бесхозяйной недвижимой вещи на учет уполномоченный государственный орган города федерального значения Москвы, Санкт-Петербурга или Севастополя может обратиться в суд с требованием о признании права собственности города федерального значения Москвы, Санкт-Петербурга или Севастополя на данную вещь. (В редакции  Федерального закона от 31.07.2025 № 315-ФЗ)\n\nБесхозяйная недвижимая вещь, не признанная по решению суда поступившей в собственность города федерального значения Москвы, Санкт-Петербурга или Севастополя, может быть вновь принята во владение, в пользование и в распоряжение оставившим ее собственником либо приобретена в собственность в силу приобретательной давности. (В редакции Федерального закона от 03.07.2016 № 333-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 09.02.2009 № 7-ФЗ)\n\nПо истечении трех месяцев со дня постановки указанных в пунктах 5 и 6 настоящей статьи бесхозяйных объектов на учет лица, обязанные в соответствии с законом осуществлять эксплуатацию таких объектов, также могут обратиться в суд с требованием о признании права собственности на такие объекты.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2025 № 315-ФЗ)","article_title":"Статья 225. Бесхозяйные вещи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"da7308a4a711fd45cbf471865c5f3319f077e75355e3b6f1516287f338f9fd0c"},{"code_id":"GK_RF","article_number":"226","version_date":"1994-11-30","article_text":"1. Движимые вещи, брошенные собственником или иным образом оставленные им с целью отказа от права собственности на них (брошенные вещи), могут быть обращены другими лицами в свою собственность в порядке, предусмотренном пунктом 2 настоящей статьи.\n\nДругие брошенные вещи поступают в собственность лица, вступившего во владение ими, если по заявлению этого лица они признаны судом бесхозяйными.","article_title":"Статья 226. Движимые вещи, от которых собственник отказался","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ef1657d7f2e53dbae844310530cb2323bdfb67005a6f474311e7d5c2481d44d9"},{"code_id":"GK_RF","article_number":"227","version_date":"1994-11-30","article_text":"1. Нашедший потерянную вещь обязан немедленно уведомить об этом лицо, потерявшее ее, или собственника вещи или кого-либо другого из известных ему лиц, имеющих право получить ее, и возвратить найденную вещь этому лицу.\n\nЕсли вещь найдена в помещении или на транспорте, она подлежит сдаче лицу, представляющему владельца этого помещения или средства транспорта. В этом случае лицо, которому сдана находка, приобретает права и несет обязанности лица, нашедшего вещь.\n\nСкоропортящаяся вещь или вещь, издержки по хранению которой несоизмеримо велики по сравнению с ее стоимостью, может быть реализована нашедшим вещь с получением письменных доказательств, удостоверяющих сумму выручки. Деньги, вырученные от продажи найденной вещи, подлежат возврату лицу, управомоченному на ее получение.","article_title":"Статья 227. Находка","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9e2fb2d9bbd8ab65239dca750b44ab2fe9ab09b81bed1eefe0c1057130cc4cca"},{"code_id":"GK_RF","article_number":"229","version_date":"1994-11-30","article_text":"1. Нашедший и возвративший вещь лицу, управомоченному на ее получение, вправе получить от этого лица, а в случаях перехода вещи в муниципальную собственность - от соответствующего органа местного самоуправления возмещение необходимых расходов, связанных с хранением, сдачей или реализацией вещи, а также затрат на обнаружение лица, управомоченного получить вещь.\n\n2. Нашедший вещь вправе потребовать от лица, управомоченного на получение вещи, вознаграждение за находку в размере до двадцати процентов стоимости вещи. Если найденная вещь представляет ценность только для лица, управомоченного на ее получение, размер вознаграждения определяется по соглашению с этим лицом.\n\nПраво на вознаграждение не возникает, если нашедший вещь не заявил о находке или пытался ее утаить.","article_title":"Статья 229. Возмещение расходов, связанных с находкой, и вознаграждение нашедшему вещь","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9c1d15aa51fce49cc88dd208976489792e1dd8ba2ce22dcefe9557d9d3b94eda"},{"code_id":"GK_RF","article_number":"23","version_date":"1994-11-30","article_text":"1. Гражданин вправе заниматься предпринимательской деятельностью без образования юридического лица с момента государственной регистрации в качестве индивидуального предпринимателя, за исключением случаев, предусмотренных абзацем вторым настоящего пункта.\n\nВ отношении отдельных видов предпринимательской деятельности законом могут быть предусмотрены условия осуществления гражданами такой деятельности без государственной регистрации в качестве индивидуального предпринимателя.\n\n(Пункт в редакции Федерального закона от 26.07.2017 № 199-ФЗ)\n\nГлавой крестьянского (фермерского) хозяйства может быть гражданин, зарегистрированный в качестве индивидуального предпринимателя.\n\n(Дополнение пунктом - Федеральный закон от 30.12.2012 № 302-ФЗ)","article_title":"Статья 23. Предпринимательская деятельность гражданина","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3e3ce314b2d00b042f38d1d91f60f34c06289397ebefe09907862355142f694f"},{"code_id":"GK_RF","article_number":"231","version_date":"1994-11-30","article_text":"1. Если в течение шести месяцев с момента заявления о задержании безнадзорных домашних животных их собственник не будет обнаружен или сам не заявит о своем праве на них, лицо, у которого животные находились на содержании и в пользовании, приобретает право собственности на них.\n\nПри отказе этого лица от приобретения в собственность содержавшихся у него животных они поступают в муниципальную собственность и используются в порядке, определяемом органом местного самоуправления.\n\n2. В случае явки прежнего собственника животных после перехода их в собственность другого лица прежний собственник вправе при наличии обстоятельств, свидетельствующих о сохранении к нему привязанности со стороны этих животных или о жестоком либо ином ненадлежащем обращении с ними нового собственника, потребовать их возврата на условиях, определяемых по соглашению с новым собственником, а при недостижении соглашения - судом.","article_title":"Статья 231. Приобретение права собственности на безнадзорных животных","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8ea1e904069eeb1240a4b953f7efc894462976875cf07c29525137642df80a8e"},{"code_id":"GK_RF","article_number":"232","version_date":"1994-11-30","article_text":"В случае возврата безнадзорных домашних животных собственнику лицо, задержавшее животных, и лицо, у которого они находились на содержании и в пользовании, имеют право на возмещение их собственником необходимых расходов, связанных с содержанием животных, с зачетом выгод, извлеченных от пользования ими.\n\nЛицо, задержавшее безнадзорных домашних животных, имеет право на вознаграждение в соответствии с пунктом 2 статьи 229 настоящего Кодекса.","article_title":"Статья 232. Возмещение расходов на содержание безнадзорных животных и вознаграждение за них","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"671275c17e8f2ff68b0d2a74e6ded70e4f6d5e4d6ab3d3d96c7e60ba4b2eeebc"},{"code_id":"GK_RF","article_number":"233","version_date":"1994-11-30","article_text":"1. Клад, то есть зарытые в земле или сокрытые иным способом деньги или ценные предметы, собственник которых не может быть установлен либо в силу закона утратил на них право, поступает в собственность лица, которому принадлежит имущество (земельный участок, строение и т.п.), где клад был сокрыт, и лица, обнаружившего клад, в равных долях, если соглашением между ними не установлено иное.\n\nПри обнаружении клада лицом, производившим раскопки или поиск ценностей без согласия на это собственника земельного участка или иного имущества, где клад был сокрыт, клад подлежит передаче собственнику земельного участка или иного имущества, где был обнаружен клад.\n\nПри обнаружении такого клада лицом, производившим раскопки или поиски ценностей без согласия собственника имущества, где клад был сокрыт, вознаграждение этому лицу не выплачиваются и полностью поступает собственнику.","article_title":"Статья 233. Клад","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9b90528e28a7813d86e5ccbb6b2ce78fe5cd96e4aed644b9dfb1bb6dca3dcaf5"},{"code_id":"GK_RF","article_number":"234","version_date":"1994-11-30","article_text":"Право собственности на недвижимое и иное имущество, подлежащее государственной регистрации, возникает у лица, приобретшего это имущество в силу приобретательной давности, с момента такой регистрации.","article_title":"Статья 234. Приобретательная давность","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a2a60728ea23153a5d9cb93aeba40e119bff529c415e412025fbfba2946e446e"},{"code_id":"GK_RF","article_number":"235","version_date":"1994-11-30","article_text":"1. Право собственности прекращается при отчуждении собственником своего имущества другим лицам, отказе собственника от права собственности, гибели или уничтожении имущества и при утрате права собственности на имущество в иных случаях, предусмотренных законом.\n\n2. Принудительное изъятие у собственника имущества не допускается, кроме случаев, когда по основаниям, предусмотренным законом, производятся:\n\n1) обращение взыскания на имущество по обязательствам (статья 237);\n\n2) отчуждение имущества, которое в силу закона не может принадлежать данному лицу (статья 238);\n\n3) отчуждение недвижимого имущества в связи с изъятием земельного участка ввиду его ненадлежащего использования (статья 239); (В редакции Федерального закона от 31.12.2014 № 499-ФЗ)\n\n31) отчуждение объекта незавершенного строительства в связи с прекращением действия договора аренды земельного участка, находящегося в государственной или муниципальной собственности (статья 2391); (Дополнение подпунктом - Федеральный закон от 23.06.2014 № 171-ФЗ)\n\n32) отчуждение недвижимого имущества в связи с принудительным отчуждением земельного участка для государственных или муниципальных нужд (изъятием земельного участка для государственных или муниципальных нужд (статья 2392);  (Дополнение подпунктом - Федеральный закон от 31.12.2014 № 499-ФЗ)\n\n4) выкуп бесхозяйственно содержимых культурных ценностей, домашних животных (статьи 240 и 241);\n\n5) реквизиция (статья 242);\n\n6) конфискация (статья 243);\n\n7) отчуждение имущества в случаях, предусмотренных статьей 2392, пунктом 4 статьи 252, пунктом 2 статьи 272, статьями 282, 285, 293, пунктами 4 и 5 статьи 1252 настоящего Кодекса; (В редакции федеральных законов от 18.12.2006 № 231-ФЗ; от 31.12.2014 № 499-ФЗ)\n\n8) обращение по решению суда в доход Российской Федерации имущества, в отношении которого не представлены в соответствии с законодательством Российской Федерации о противодействии коррупции доказательства его приобретения на законные доходы; (Дополнение подпунктом - Федеральный закон от 03.12.2012 № 231-ФЗ)\n\n9) обращение по решению суда в доход Российской Федерации денег, ценностей, иного имущества и доходов от них, в отношении которых в соответствии с законодательством Российской Федерации о противодействии терроризму лицом не представлены сведения, подтверждающие законность их приобретения. (Дополнение подпунктом - Федеральный закон от 02.11.2013 № 302-ФЗ)\n\nПо решению собственника в порядке, предусмотренном законами о приватизации, имущество, находящееся в государственной или муниципальной собственности, отчуждается в собственность граждан и юридических лиц.\n\nОбращение в государственную собственность имущества, находящегося в собственности граждан и юридических лиц (национализация), производится на основании закона с возмещением стоимости этого имущества и других убытков в порядке, установленном статьей 306 настоящего Кодекса.","article_title":"Статья 235. Основания прекращения права собственности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"46ed3a77df695ac6b311a175df53597ef8c895e8893de5822bd2129ca6d35b60"},{"code_id":"GK_RF","article_number":"236","version_date":"1994-11-30","article_text":"Гражданин или юридическое лицо может отказаться от права собственности на принадлежащее ему имущество, объявив об этом либо совершив другие действия, определенно свидетельствующие о его устранении от владения, пользования и распоряжения имуществом без намерения сохранить какие-либо права на это имущество.\n\nОтказ от права собственности не влечет прекращения прав и обязанностей собственника в отношении соответствующего имущества до приобретения права собственности на него другим лицом.","article_title":"Статья 236. Отказ от права собственности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5f7a3e1d962fc1949122f96b934dde69df58acd448b4c9eaf428c66b9b9f7c73"},{"code_id":"GK_RF","article_number":"237","version_date":"1994-11-30","article_text":"1. Изъятие имущества путем обращения взыскания на него по обязательствам собственника производится на основании решения суда, если иной порядок обращения взыскания не предусмотрен законом или договором.\n\n2. Право собственности на имущество, на которое обращается взыскание, прекращается у собственника с момента возникновения права собственности на изъятое имущество у лица, к которому переходит это имущество.","article_title":"Статья 237. Обращение взыскания на имущество по обязательствам собственника","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"efc8713b4ca372d8d353033507c6e8dcbd596794901179a696a8c7b020fcc403"},{"code_id":"GK_RF","article_number":"238","version_date":"1994-11-30","article_text":"1. Если по основаниям, допускаемым законом, в собственности лица оказалось имущество, которое в силу закона не может ему принадлежать, это имущество должно быть отчуждено собственником в течение года с момента возникновения права собственности на имущество, если законом не установлен иной срок.","article_title":"Статья 238. Прекращение права собственности лица на имущество, которое не может ему принадлежать","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2a4eefe1bdd208e5637524cff385ed84a3bbc899883dda393bd20ef3b74c0982"},{"code_id":"GK_RF","article_number":"239","version_date":"1994-11-30","article_text":"Абзац. (Утратил силу - Федеральный закон от 31.12.2014 № 499-ФЗ)","article_title":"Статья 239. Отчуждение недвижимого имущества в связи с изъятием участка, на котором оно находится","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1d801b10cdd727660fe29d19bdc6a620da1146e9b891e91430c2465e15a2dae3"},{"code_id":"GK_RF","article_number":"239.1","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено законом, в случае прекращения действия договора аренды земельного участка, находящегося в государственной или муниципальной собственности и предоставленного по результатам аукциона, объекты незавершенного строительства, расположенные на таком земельном участке, могут быть изъяты у собственника по решению суда путем продажи с публичных торгов.\n\nПорядок проведения публичных торгов по продаже объектов незавершенного строительства устанавливается Правительством Российской Федерации.\n\n2. Требование в суд о продаже объекта незавершенного строительства с публичных торгов вправе заявить исполнительный орган государственной власти или орган местного самоуправления, уполномоченные на распоряжение земельным участком, который находится в государственной или муниципальной собственности и на котором расположен этот объект.\n\n3. Требование о продаже объекта незавершенного строительства не подлежит удовлетворению, если собственник этого объекта докажет, что нарушение срока строительства объекта связано с действиями (бездействием) органов государственной власти, органов местного самоуправления или лиц, осуществляющих эксплуатацию сетей инженерно-технического обеспечения, к которым должен быть подключен (технологически присоединен) объект.\n\n4. Начальная цена продажи объекта незавершенного строительства определяется на основании оценки его рыночной стоимости.\n\nЕсли публичные торги по продаже объекта незавершенного строительства признаны несостоявшимися, такой объект может быть приобретен в государственную или муниципальную собственность по начальной цене этого объекта в течение двух месяцев со дня признания торгов несостоявшимися.\n\n5. Средства, вырученные от продажи объекта незавершенного строительства с публичных торгов либо приобретения такого объекта в государственную или муниципальную собственность, выплачиваются бывшему собственнику объекта за вычетом расходов на подготовку и проведение публичных торгов.\n\n6. Правила настоящей статьи применяются также в случае прекращения действия договора аренды земельного участка, находящегося в государственной или муниципальной собственности, который заключен без проведения торгов в целях завершения строительства объекта незавершенного строительства, при условии, что строительство этого объекта не было завершено.\n\n(Дополнение статьей - Федеральный закон от 23.06.2014 № 171-ФЗ)","article_title":"Статья 239.1. Отчуждение объекта незавершенного строительства, расположенного на земельном участке, находящемся в государственной или муниципальной собственности, в связи с прекращением действия договора аренды такого земельного участка","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dc7366060c18fe681af5155bb7151394b11e089afc1109f90a43bf343c487f2e"},{"code_id":"GK_RF","article_number":"239.2","version_date":"1994-11-30","article_text":"(Дополнение статьей - Федеральный закон от 31.12.2014 № 499-ФЗ)","article_title":"Статья 239.2. Отчуждение недвижимого имущества в связи с изъятием земельного участка для государственных или муниципальных нужд","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8f840809c8f113b046ab71ed57bd6533ea11cf68b676e6ec627a5f9257356fe9"},{"code_id":"GK_RF","article_number":"24","version_date":"1994-11-30","article_text":"Гражданин отвечает по своим обязательствам всем принадлежащим ему имуществом, за исключением имущества, на которое в соответствии с законом не может быть обращено взыскание.\n\nПеречень имущества граждан, на которое не может быть обращено взыскание, устанавливается гражданским процессуальным законодательством.","article_title":"Статья 24. Имущественная ответственность гражданина","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9b14c0a717df2aedc142535701d5c4eebfcaeefd61dd4b9eb99c055a5af46f6e"},{"code_id":"GK_RF","article_number":"240","version_date":"1994-11-30","article_text":"В случаях, когда собственник культурных ценностей, отнесенных в соответствии с законом к особо ценным и охраняемым государством, бесхозяйственно содержит эти ценности, что грозит утратой ими своего значения, такие ценности по решению суда могут быть изъяты у собственника путем выкупа государством или продажи с публичных торгов.\n\nПри выкупе культурных ценностей собственнику возмещается их стоимость в размере, установленном соглашением сторон, а в случае спора - судом. При продаже с публичных торгов собственнику передается вырученная от продажи сумма за вычетом расходов на проведение торгов, а также стоимости восстановительных работ в отношении объекта культурного наследия, или стоимости мероприятий, необходимых для сохранения объекта археологического наследия, указанных в статье 40 Федерального закона от 25 июня 2002 года № 73-ФЗ \"Об объектах культурного наследия (памятниках истории и культуры) народов Российской Федерации\". (В редакции Федерального закона от 22.10.2014 № 315-ФЗ)","article_title":"Статья 240. Выкуп бесхозяйственно содержимых культурных ценностей","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"37d916ddacf110ae6be514f6fb4d640a222768a773b73dac3e5e11a5d09e6237"},{"code_id":"GK_RF","article_number":"241","version_date":"1994-11-30","article_text":"В случаях, когда собственник домашних животных обращается с ними в явном противоречии с установленными на основании закона правилами и принятыми в обществе нормами гуманного отношения к животным, эти животные могут быть изъяты у собственника путем их выкупа лицом, предъявившим соответствующее требование в суд. Цена выкупа определяется соглашением сторон, а в случае спора - судом.","article_title":"Статья 241. Выкуп домашних животных при ненадлежащем обращении с ними","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"458f71f6323a8af34027a03ed6d72df83b79cfed6310180819359ca69a6eb551"},{"code_id":"GK_RF","article_number":"242","version_date":"1994-11-30","article_text":"1. В случаях стихийных бедствий, аварий, эпидемий, эпизоотий и при иных обстоятельствах, носящих чрезвычайный характер, имущество в интересах общества по решению государственных органов может быть изъято у собственника в порядке и на условиях, установленных законом, с выплатой ему стоимости имущества (реквизиция).\n\n2. Оценка, по которой собственнику возмещается стоимость реквизированного имущества, может быть оспорена им в суде.\n\n3. Лицо, имущество которого реквизировано, вправе при прекращении действия обстоятельств, в связи с которыми произведена реквизиция, требовать по суду возврата ему сохранившегося имущества.","article_title":"Статья 242. Реквизиция","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"61cdffcd28232156463ce72a3c0d2ef1e787c244f61a91f681d8d432fb6dc1d1"},{"code_id":"GK_RF","article_number":"243","version_date":"1994-11-30","article_text":"1. В случаях, предусмотренных законом, имущество может быть безвозмездно изъято у собственника по решению суда в виде санкции за совершение преступления или иного правонарушения (конфискация).\n\n(Дополнение абзацем - Федеральный закон от 24.07.2023 № 351-ФЗ)","article_title":"Статья 243. Конфискация","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7cc5728fcbf4b1458c12555717cbafe8cf86d75ac463f4a13ee951ce65b99368"},{"code_id":"GK_RF","article_number":"244","version_date":"1994-11-30","article_text":"1. Имущество, находящееся в собственности двух или нескольких лиц, принадлежит им на праве общей собственности.\n\n2. Имущество может находиться в общей собственности с определением доли каждого из собственников в праве собственности (долевая собственность) или без определения таких долей (совместная собственность).\n\n3. Общая собственность на имущество является долевой, за исключением случаев, когда законом предусмотрено образование совместной собственности на это имущество.\n\n4. Общая собственность возникает при поступлении в собственность двух или нескольких лиц имущества, которое не может быть разделено без изменения его назначения (неделимые вещи) либо не подлежит разделу в силу закона.\n\nОбщая собственность на делимое имущество возникает в случаях, предусмотренных законом или договором.\n\n5. По соглашению участников совместной собственности, а при недостижении согласия по решению суда на общее имущество может быть установлена долевая собственность этих лиц.","article_title":"Статья 244. Понятие и основания возникновения общей собственности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"baf79a5372e3172854783daf297b35461c6c113d492b8003823cbb7fb3e0fcba"},{"code_id":"GK_RF","article_number":"245","version_date":"1994-11-30","article_text":"1. Если доли участников долевой собственности не могут быть определены на основании закона и не установлены соглашением всех ее участников, доли считаются равными.\n\n2. Соглашением всех участников долевой собственности может быть установлен порядок определения и изменения их долей в зависимости от вклада каждого из них в образование и приращение общего имущества.\n\n3. Участник долевой собственности, осуществивший за свой счет с соблюдением установленного порядка использования общего имущества неотделимые улучшения этого имущества, имеет право на соответствующее увеличение своей доли в праве на общее имущество.\n\nОтделимые улучшения общего имущества, если иное не предусмотрено соглашением участников долевой собственности, поступают в собственность того из участников, который их произвел.","article_title":"Статья 245. Определение долей в праве долевой собственности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"78c944cd559405f49cfb4712372cf5f31d6fc7dc90d003210fe9ad67241a9440"},{"code_id":"GK_RF","article_number":"246","version_date":"1994-11-30","article_text":"1. Распоряжение имуществом, находящимся в долевой собственности, осуществляется по соглашению всех ее участников.\n\n2. Участник долевой собственности вправе по своему усмотрению продать, подарить, завещать, отдать в залог свою долю либо распорядиться ею иным образом с соблюдением при ее возмездном отчуждении правил, предусмотренных статьей 250 настоящего Кодекса.","article_title":"Статья 246. Распоряжение имуществом, находящимся в долевой собственности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e5cb8491b406a0e9ddd340c3cb15dc803cef761f587ca7808450aee172a5da04"},{"code_id":"GK_RF","article_number":"247","version_date":"1994-11-30","article_text":"1. Владение и пользование имуществом, находящимся в долевой собственности, осуществляются по соглашению всех ее участников, а при недостижении согласия - в порядке, устанавливаемом судом.\n\n2. Участник долевой собственности имеет право на предоставление в его владение и пользование части общего имущества, соразмерной его доле, а при невозможности этого вправе требовать от других участников, владеющих и пользующихся имуществом, приходящимся на его долю, соответствующей компенсации.","article_title":"Статья 247. Владение и пользование имуществом, находящимся в долевой собственности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5061305d604f57efe40133a162bb0dd92565bc7e2959c3e877ff4b399f0e81a8"},{"code_id":"GK_RF","article_number":"248","version_date":"1994-11-30","article_text":"Плоды, продукция и доходы от использования имущества, находящегося в долевой собственности, поступают в состав общего имущества и распределяются между участниками долевой собственности соразмерно их долям, если иное не предусмотрено соглашением между ними.","article_title":"Статья 248. Плоды, продукция и доходы от использования имущества, находящегося в долевой собственности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e0aba76e9c6976b4d95acb636832fddb65138acd06f1a1001d2be27faef22e1b"},{"code_id":"GK_RF","article_number":"249","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 24.07.2023 № 351-ФЗ)\n\nКаждый участник долевой собственности обязан соразмерно со своей долей участвовать в уплате налогов, сборов и иных обязательных платежей по общему имуществу, а также в расходах и издержках по его содержанию и сохранению. (В редакции  Федерального закона от 24.07.2023 № 351-ФЗ)","article_title":"Статья 249. Бремя содержания имущества, находящегося в долевой собственности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"62c654365e4086be6b9b90d5a1adfed423d3abd32a63db434a3e4bf30d871526"},{"code_id":"GK_RF","article_number":"25","version_date":"1994-11-30","article_text":"1. Гражданин, который не способен удовлетворить требования кредиторов по денежным обязательствам и (или) исполнить обязанность по уплате обязательных платежей, может быть признан несостоятельным (банкротом) по решению арбитражного суда.\n\n2. Основания, порядок и последствия признания арбитражным судом гражданина несостоятельным (банкротом), очередность удовлетворения требований кредиторов, порядок применения процедур в деле о несостоятельности (банкротстве) гражданина устанавливаются законом, регулирующим вопросы несостоятельности (банкротства).\n\n(Статья в редакции Федерального закона от 29.06.2015 № 154-ФЗ)","article_title":"Статья 25. Несостоятельность (банкротство) гражданина","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"111437fcd884089602b96a071cfe392be5e17cb432a8689487f1ff01ba897492"},{"code_id":"GK_RF","article_number":"250","version_date":"1994-11-30","article_text":"Публичные торги для продажи доли в праве общей собственности при отсутствии согласия на это всех участников долевой собственности могут проводиться в случаях, предусмотренных частью второй статьи 255 настоящего Кодекса, и в иных случаях, предусмотренных законом.\n\nЕсли остальные участники долевой собственности не приобретут продаваемую долю в праве собственности на недвижимое имущество в течение месяца, а в праве собственности на движимое имущество в течение десяти дней со дня извещения, продавец вправе продать свою долю любому лицу. В случае, если все остальные участники долевой собственности в письменной форме откажутся от реализации преимущественного права покупки продаваемой доли, такая доля может быть продана постороннему лицу ранее указанных сроков.\n\nОсобенности извещения участников долевой собственности о намерении продавца доли в праве общей собственности продать свою долю постороннему лицу могут быть установлены федеральным законом.\n\n(Пункт в редакции Федерального закона от 03.07.2016 № 315-ФЗ)","article_title":"Статья 250. Преимущественное право покупки","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"14f0acddb6fcf40fc9cff2f059fc7c8307a0cabfaa20711c58999ad46e160bcc"},{"code_id":"GK_RF","article_number":"251","version_date":"1994-11-30","article_text":"Доля в праве общей собственности переходит к приобретателю по договору с момента заключения договора, если соглашением сторон не предусмотрено иное.\n\nМомент перехода доли в праве общей собственности по договору, подлежащему государственной регистрации, определяется в соответствии с пунктом 2 статьи 223 настоящего Кодекса.","article_title":"Статья 251. Момент перехода доли в праве общей собственности к приобретателю по договору","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4aaf214912050a0003996b360640981797d56c571bb558a8e5d02d2bb5c60cb3"},{"code_id":"GK_RF","article_number":"252","version_date":"1994-11-30","article_text":"1. Имущество, находящееся в долевой собственности, может быть разделено между ее участниками по соглашению между ними.\n\n2. Участник долевой собственности вправе требовать выдела своей доли из общего имущества.\n\n3. При недостижении участниками долевой собственности соглашения о способе и условиях раздела общего имущества или выдела доли одного из них участник долевой собственности вправе в судебном порядке требовать выдела в натуре своей доли из общего имущества.\n\nЕсли выдел доли в натуре не допускается законом или невозможен без несоразмерного ущерба имуществу, находящемуся в общей собственности, выделяющийся собственник имеет право на выплату ему стоимости его доли другими участниками долевой собственности.\n\n4. Несоразмерность имущества, выделяемого в натуре участнику долевой собственности на основании настоящей статьи, его доле в праве собственности устраняется выплатой соответствующей денежной суммы или иной компенсацией.\n\nВыплата участнику долевой собственности остальными собственниками компенсации вместо выдела его доли в натуре допускается с его согласия. В случаях, когда доля собственника незначительна, не может быть реально выделена и он не имеет существенного интереса в использовании общего имущества, суд может и при отсутствии согласия этого собственника обязать остальных участников долевой собственности выплатить ему компенсацию.\n\n5. С получением компенсации в соответствии с настоящей статьей собственник утрачивает право на долю в общем имуществе.","article_title":"Статья 252. Раздел имущества, находящегося в долевой собственности, и выдел из него доли","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"100d76d3394c5e725acbcb56393af7435d16e5e0fc9b8a1e2da492f42a2898f1"},{"code_id":"GK_RF","article_number":"253","version_date":"1994-11-30","article_text":"1. Участники совместной собственности, если иное не предусмотрено соглашением между ними, сообща владеют и пользуются общим имуществом.\n\n2. Распоряжение имуществом, находящимся в совместной собственности, осуществляется по согласию всех участников, которое предполагается независимо от того, кем из участников совершается сделка по распоряжению имуществом.\n\n3. Каждый из участников совместной собственности вправе совершать сделки по распоряжению общим имуществом, если иное не вытекает из соглашения всех участников. Совершенная одним из участников совместной собственности сделка, связанная с распоряжением общим имуществом, может быть признана недействительной по требованию остальных участников по мотивам отсутствия у участника, совершившего сделку, необходимых полномочий только в случае, если доказано, что другая сторона в сделке знала или заведомо должна была знать об этом.\n\n4. Правила настоящей статьи применяются\n\nпостольку, поскольку для отдельных видов совместной собственности настоящим Кодексом или другими законами не установлено иное.","article_title":"Статья 253. Владение, пользование и распоряжение имуществом, находящимся в совместной собственности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"38a022f27e1938e44519c2d653c6bb9765e5141c4ec020bba7d2a0b9d722f9a0"},{"code_id":"GK_RF","article_number":"254","version_date":"1994-11-30","article_text":"1. Раздел общего имущества между участниками совместной собственности, а также выдел доли одного из них могут быть осуществлены после предварительного определения доли каждого из участников в праве на общее имущество.\n\n2. При разделе общего имущества и выделе из него доли, если иное не предусмотрено законом или соглашением участников, их доли признаются равными.\n\n3. Основания и порядок раздела общего имущества и выдела из него доли определяются по правилам статьи 252 настоящего Кодекса постольку, поскольку иное для отдельных видов совместной собственности не установлено настоящим Кодексом, другими законами и не вытекает из существа отношений участников совместной собственности.","article_title":"Статья 254. Раздел имущества, находящегося в совместной собственности, и выдел из него доли","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bb8c39b625efb7f797a3d8d2e4c37f0b0057ef5dbc7ac311666abb990a65ca83"},{"code_id":"GK_RF","article_number":"255","version_date":"1994-11-30","article_text":"Кредитор участника долевой или совместной собственности при недостаточности у собственника другого имущества вправе предъявить требование о выделе доли должника в общем имуществе для обращения на нее взыскания.\n\nЕсли в таких случаях выделение доли в натуре невозможно либо против этого возражают остальные участники долевой или совместной собственности, кредитор вправе требовать продажи должником своей доли остальным участникам общей собственности по цене, соразмерной рыночной стоимости этой доли, с обращением вырученных от продажи средств в погашение долга.\n\nВ случае отказа остальных участников общей собственности от приобретения доли должника кредитор вправе требовать по суду обращения взыскания на долю должника в праве общей собственности путем продажи этой доли с публичных торгов.","article_title":"Статья 255. Обращение взыскания на долю в общем имуществе","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"de191f33fcd9768bdaa0dd0e75995a6a22df00ce6eead77f00d6f9891cf8c824"},{"code_id":"GK_RF","article_number":"256","version_date":"1994-11-30","article_text":"Вещи индивидуального пользования (одежда, обувь и т.п.), за исключением драгоценностей и других предметов роскоши, хотя и приобретенные во время брака за счет общих средств супругов, признаются собственностью того супруга, который ими пользовался.\n\nИмущество каждого из супругов может быть признано судом их совместной собственностью, если будет установлено, что в течение брака за счет общего имущества супругов или личного имущества другого супруга были произведены вложения, значительно увеличивающие стоимость этого имущества (капитальный ремонт, реконструкция, переоборудование и т.п.). Настоящее правило не применяется, если брачным договором между супругами предусмотрено иное. (В редакции федеральных законов от 30.12.2015 № 457-ФЗ, от 19.07.2018 № 217-ФЗ)\n\nИсключительное право на результат интеллектуальной деятельности, принадлежащее автору такого результата (статья 1228), не входит в общее имущество супругов. Однако доходы, полученные от использования такого результата, являются совместной собственностью супругов, если брачным договором между ними не предусмотрено иное. (Дополнение абзацем - Федеральный закон от 18.12.2006 № 231-ФЗ) (В редакции Федерального закона от 19.07.2018 № 217-ФЗ)\n\nВ случае смерти одного из супругов пережившему супругу принадлежит доля в праве на общее имущество супругов, равная одной второй, если иной размер доли не был определен брачным договором, совместным завещанием супругов, наследственным договором или решением суда. (Дополнение абзацем - Федеральный закон от 19.07.2018 № 217-ФЗ)","article_title":"Статья 256. Общая собственность супругов","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d3f39e75e069f4658b41038fe2ceed86c3cd278daca6f66c218d24ea9f27aa5e"},{"code_id":"GK_RF","article_number":"257","version_date":"1994-11-30","article_text":"1. Имущество крестьянского (фермерского) хозяйства принадлежит его членам на праве совместной собственности, если законом или договором между ними не установлено иное.","article_title":"Статья 257. Собственность крестьянского (фермерского) хозяйства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"01b9c8826a967164cd2808d942e95153a15b13a184c7ecc964e70f8622fe8d42"},{"code_id":"GK_RF","article_number":"258","version_date":"1994-11-30","article_text":"1. При прекращении крестьянского (фермерского) хозяйства в связи с выходом из него всех его членов или по иным основаниям общее имущество подлежит разделу по правилам, предусмотренным статьями 252 и 254 настоящего Кодекса.\n\nЗемельный участок в таких случаях делится по правилам, установленным настоящим Кодексом и земельным законодательством.\n\n2. Земельный участок и средства производства, принадлежащие крестьянскому (фермерскому) хозяйству, при выходе одного из его членов из хозяйства разделу не подлежат. Вышедший из хозяйства имеет право на получение денежной компенсации, соразмерной его доле в общей собственности на это имущество.\n\n3. В случаях, предусмотренных настоящей статьей, доли членов крестьянского (фермерского) хозяйства в праве совместной собственности на имущество хозяйства признаются равными, если соглашением между ними не установлено иное.","article_title":"Статья 258. Раздел имущества крестьянского (фермерского) хозяйства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ba3658a6b87aca84551af713110856e36e5b627e7caaae0a8700259b28e4ef81"},{"code_id":"GK_RF","article_number":"259","version_date":"1994-11-30","article_text":"1. Членами крестьянского (фермерского) хозяйства на базе имущества хозяйства может быть создано хозяйственное товарищество или производственный кооператив. Такое хозяйственное товарищество или кооператив как юридическое лицо обладает правом собственности на имущество, переданное ему в форме вкладов и других взносов членами фермерского хозяйства, а также на имущество, полученное в результате его деятельности и приобретенное по иным основаниям, допускаемым законом.\n\n2. Размер вкладов участников товарищества или членов кооператива, созданного на базе имущества крестьянского (фермерского) хозяйства, устанавливается исходя из их долей в праве общей собственности на имущество хозяйства, определяемых в соответствии с пунктом 3 статьи 258 настоящего Кодекса.\n\n(Дополнение параграфом - Федеральный закон от 24.07.2023 № 351-ФЗ)","article_title":"Статья 259. Собственность хозяйственного товарищества или кооператива, образованного на базе имущества крестьянского (фермерского) хозяйства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0f36f02ac08b0a766d772c817e11b6fe15af32f0bfe2733b931f2a21b80e0c55"},{"code_id":"GK_RF","article_number":"259.1","version_date":"1994-11-30","article_text":"1. Собственникам недвижимых вещей, расположенных в пределах определенной в соответствии с законом общей территории и связанных физически или технологически либо расположенных в здании или сооружении, принадлежит на праве общей долевой собственности имущество, использование которого предполагалось для удовлетворения общих потребностей таких собственников при создании или образовании этих недвижимых вещей, а также имущество, приобретенное, созданное или образованное в дальнейшем для этой же цели (общее имущество).\n\n2. Если в порядке, установленном законом, определены границы общей территории и предусмотрено создание на ней общего имущества, то собственникам земельных участков, расположенных на этой территории, принадлежат также доли в праве общей собственности на земельные участки общего назначения, если иное не предусмотрено законом.\n\n3. Состав общего имущества может быть определен в соответствии с законом.\n\n4. Если принадлежащее собственнику здание или сооружение расположено на земельном участке, собственником которого является иное лицо, то законом может быть предусмотрено, что доля в праве общей собственности на общее имущество принадлежит такому собственнику здания или сооружения.\n\n5. Собственник недвижимой вещи вправе получать информацию о любых решениях, принятых общим собранием собственников недвижимых вещей, от лиц, на которых в силу закона или решения общего собрания собственников возложены обязанности по хранению такой информации.\n\n6. Положения параграфа 1 настоящей главы применяются к отношениям собственников недвижимых вещей по поводу принадлежащего им общего имущества, если иное не предусмотрено настоящей статьей и статьями 2592 - 2594 настоящего Кодекса.","article_title":"Статья 259.1. Право общей долевой собственности собственников недвижимых вещей на общее имущество","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4091e8f807d5f631df656e158be7241a0bf78323c6e09ab6aaf5a62b35e32f28"},{"code_id":"GK_RF","article_number":"259.2","version_date":"1994-11-30","article_text":"1. Доля в праве общей собственности на общее имущество, принадлежащая собственнику одной недвижимой вещи, пропорциональна площади принадлежащей ему соответствующей недвижимой вещи, если иное не установлено законом.\n\n2. Доля в праве общей собственности на общее имущество следует судьбе права собственности на недвижимую вещь, не может быть выделена в натуре и не может быть отчуждена отдельно от права собственности на недвижимую вещь. Собственник недвижимой вещи не вправе также совершать иные действия, влекущие передачу такой доли отдельно от права собственности на недвижимую вещь. Сделки, совершенные с нарушением положений настоящего пункта, ничтожны.","article_title":"Статья 259.2. Доля в праве общей собственности на общее имущество","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"404f29a0404754ac42ce0a40ba57a5a21873eb05e9c0c420863ad251831e87d9"},{"code_id":"GK_RF","article_number":"259.3","version_date":"1994-11-30","article_text":"1. Каждый собственник недвижимой вещи вправе владеть и пользоваться общим имуществом наряду с собственниками иных недвижимых вещей, если иной порядок не определен решением собственников недвижимых вещей, настоящим Кодексом или законом.\n\n2. За исключением случаев, предусмотренных пунктами 4 и 5 настоящей статьи, решение собственников недвижимых вещей по вопросам владения, пользования и распоряжения общим имуществом принимается большинством голосов всех собственников недвижимых вещей, если иное число голосов не предусмотрено настоящим Кодексом или законом.\n\n3. Количество голосов, принадлежащих собственнику недвижимой вещи, пропорционально размеру принадлежащей ему доли в праве собственности на общее имущество.\n\n4. Пригодное для самостоятельного использования общее имущество может быть передано во владение или пользование третьим лицам, если такая передача не повлечет нарушение прав и охраняемых законом интересов собственников недвижимых вещей. Передача общего имущества во владение или пользование третьим лицам осуществляется на основании решения собственников недвижимых вещей, принятого не менее чем двумя третями голосов собственников недвижимых вещей.\n\n5. Недвижимые вещи, относящиеся к общему имуществу, не подлежат передаче в собственность третьим лицам, за исключением случаев, если решение об этой передаче принято собственниками недвижимых вещей единогласно при условии, что эта передача не противоречит закону.","article_title":"Статья 259.3. Владение, пользование и распоряжение общим имуществом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0bec0f7f4e23bc0c64389570f7d4fea2a04e62504fa87314c62a64f749b460d6"},{"code_id":"GK_RF","article_number":"259.4","version_date":"1994-11-30","article_text":"1. Если иное не установлено единогласным решением собственников недвижимых вещей, каждый собственник недвижимой вещи обязан участвовать в расходах и издержках по содержанию и сохранению общего имущества соразмерно со своей долей в праве на общее имущество (пункт 1 статьи 2592). Собственник недвижимой вещи, в результате действий или бездействия которого возникают дополнительные расходы и издержки по содержанию и сохранению общего имущества, обязан их покрывать.\n\n2. Каждый собственник недвижимой вещи обязан соразмерно со своей долей в праве общей собственности на общее имущество (пункт 1 статьи 2592) участвовать в уплате налогов, сборов и иных обязательных платежей, связанных с общим имуществом.\n\n(Наименование в редакции Федерального закона от 16.04.2001 № 45-ФЗ)\n\n____________________________\n\n* (Сноска исключена - Федеральный закон от 16.04.2001 № 45-ФЗ)","article_title":"Статья 259.4. Бремя содержания общего имущества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"38f94279b2ebbe509be61458a744aa9a3ec5663367f0f058cc7342d50a4a8563"},{"code_id":"GK_RF","article_number":"26","version_date":"1994-11-30","article_text":"1. Несовершеннолетние в возрасте от четырнадцати до восемнадцати лет совершают сделки, за исключением названных в пункте 2 настоящей статьи, с письменного согласия своих законных представителей - родителей, усыновителей или попечителя.\n\nСделка, совершенная таким несовершеннолетним, действительна также при ее последующем письменном одобрении его родителями, усыновителями или попечителем.\n\n2. Несовершеннолетние в возрасте от четырнадцати до восемнадцати лет вправе самостоятельно, без согласия родителей, усыновителей и попечителя:\n\n1) распоряжаться своими заработком, стипендией и иными доходами;\n\n2) осуществлять права автора произведения науки, литературы или искусства, изобретения или иного охраняемого законом результата своей интеллектуальной деятельности;\n\n3) в соответствии с законом вносить вклады в кредитные организации и распоряжаться ими; (В редакции Федерального закона от 30.12.2012 № 302-ФЗ)\n\n4) совершать мелкие бытовые сделки и иные сделки, предусмотренные пунктом 2 статьи 28 настоящего Кодекса.\n\nПо достижении шестнадцати лет несовершеннолетние также вправе быть членами кооперативов в соответствии с законами о кооперативах.\n\n3. Несовершеннолетние в возрасте от четырнадцати до восемнадцати лет самостоятельно несут имущественную ответственность по сделкам, совершенным ими в соответствии с пунктами 1 и 2 настоящей статьи. За причиненный ими вред такие несовершеннолетние несут ответственность в соответствии с настоящим Кодексом.\n\n4. При наличии достаточных оснований суд по ходатайству родителей, усыновителей или попечителя либо органа опеки и попечительства может ограничить или лишить несовершеннолетнего в возрасте от четырнадцати до восемнадцати лет права самостоятельно распоряжаться своими заработком, стипендией или иными доходами, за исключением случаев, когда такой несовершеннолетний приобрел дееспособность в полном объеме в соответствии с пунктом 2 статьи 21 или со статьей 27 настоящего Кодекса.","article_title":"Статья 26. Дееспособность несовершеннолетних в возрасте от четырнадцати до восемнадцати лет","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c7ba5a4e9bb5a9d37ba43cb75f8d1f18e07d97a94e116c344b570cd32d3985ca"},{"code_id":"GK_RF","article_number":"260","version_date":"1994-11-30","article_text":"1. Лица, имеющие в собственности земельный участок, вправе продавать его, дарить, отдавать в залог или сдавать в аренду и распоряжаться им иным образом (статья 209) постольку, поскольку соответствующие земли на основании закона не исключены из оборота или не ограничены в обороте.","article_title":"Статья 260. Общие положения о праве собственности на землю","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3d7325c7dcccc17ac76253f8c8fb14c888d0c075766454cfce8b2bca21c58cea"},{"code_id":"GK_RF","article_number":"262","version_date":"1994-11-30","article_text":"1. Граждане имеют право свободно, без каких-либо разрешений находиться на не закрытых для общего доступа земельных участках, находящихся в государственной или муниципальной собственности, и использовать имеющиеся на этих участках природные объекты в пределах, допускаемых законом и иными правовыми актами, а также собственником соответствующего земельного участка.\n\n2. Если земельный участок не огорожен либо его собственник иным способом ясно не обозначил, что вход на участок без его разрешения не допускается, любое лицо может пройти через участок при условии, что это не причиняет ущерба или беспокойства собственнику.","article_title":"Статья 262. Земельные участки общего пользования. Доступ на земельный участок","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d99e902b5c5fcaf95ec84312ce01043b2af553ca2e902a0af109b30efba01905"},{"code_id":"GK_RF","article_number":"263","version_date":"1994-11-30","article_text":"Последствия самовольной постройки, возведенной или созданной на земельном участке его собственником или другими лицами, определяются статьей 222 настоящего Кодекса. (В редакции Федерального закона от 03.08.2018 № 339-ФЗ)","article_title":"Статья 263. Застройка земельного участка","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"eefb2d2fd46c5048acf41528efa5b8b3bbfca067f67917d3ac3a72c0eb0411f2"},{"code_id":"GK_RF","article_number":"265","version_date":"1994-11-30","article_text":"Право пожизненного наследуемого владения земельным участком, находящимся в государственной или муниципальной собственности, приобретается гражданами по основаниям и в порядке, которые предусмотрены земельным законодательством.","article_title":"Статья 265. Основания приобретения права пожизненного наследуемого владения земельным участком","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"28f23bb57edc32982329e39835b80b639e160688f5cd613844af53c8ef5ca754"},{"code_id":"GK_RF","article_number":"266","version_date":"1994-11-30","article_text":"1. Гражданин, обладающий правом пожизненного наследуемого владения (владелец земельного участка), имеет права владения и пользования земельным участком, передаваемые по наследству.\n\n2. Если из условий пользования земельным участком, установленных законом, не вытекает иное, владелец земельного участка вправе возводить на нем здания, сооружения и создавать другое недвижимое имущество, приобретая на него право собственности.","article_title":"Статья 266. Владение и пользование земельным участком на праве пожизненного наследуемого владения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a76d26713b5b80d12f40433eb3ca68294a3ad3926484d6f65d4e8b6620d137f8"},{"code_id":"GK_RF","article_number":"267","version_date":"1994-11-30","article_text":"Распоряжение земельным участком, находящимся в пожизненном наследуемом владении, не допускается, за исключением случая перехода права на земельный участок по наследству.\n\n(Статья в редакции Федерального закона от 26.06.2007 № 118-ФЗ)","article_title":"Статья 267. Распоряжение земельным участком, находящимся в пожизненном наследуемом владении","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e6f4abafe92aa2cb78e76a7bfc2dc48cb88122acf2c9637bc5450567d34d2eb7"},{"code_id":"GK_RF","article_number":"269","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 26.06.2007 № 118-ФЗ)","article_title":"Статья 269. Владение и пользование землей на праве постоянного (бессрочного) пользования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"870c2b91ffceaf0f97e66ccaca7dbb0e5e7d516f363d8baef1cfec2d84300b08"}]$law7d0022$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
commit;
